REXCVAR_DEFINE_BOOL(rexnative_frame_generation, false, "ReXNative",
                    "Present a frame generated by AMD FidelityFX Frame Generation "
                    "(amd_fidelityfx_framegeneration_dx12.dll beside the executable, or what "
                    "OptiScaler puts behind it) before each frame, from the upscaler's depth and "
                    "motion, at half the display's refresh rate: with --rexnative_upscaler "
                    "(bind_upscaler, F7) and the frame pacer (--rexnative)");

namespace rexnative {

namespace {

namespace xenos = rex::graphics::xenos;

// A color target's EDRAM data: its base and storage format, which a format's _AS_16_16_16_16
// variant shares (PGR4 composites the front buffer in 2_10_10_10_FLOAT and draws the HUD over it
// in 2_10_10_10_FLOAT_AS_16_16_16_16, td-265).
uint32_t ColorStorage(uint32_t color_info) {
  const auto format = xenos::ColorRenderTargetFormat((color_info >> 16) & 0xF);
  return (color_info & 0xFFF) | uint32_t(xenos::GetStorageColorFormat(format)) << 16;
}

}  // namespace

REXCVAR_DEFINE_BOOL(rexnative_frame_generation_hudless, true, "ReXNative",
                    "Frame generation takes the HUD from where the frame and a copy of it made "
                    "before the HUD's draws differ (FidelityFX's HUDLessColor); false: no copy, "
                    "the HUD is generated with the scene (live)");

REXCVAR_DEFINE_BOOL(rexnative_frame_generation_indicators, false, "ReXNative",
                    "Frame generation's debug indicators on the generated frames (live): its tear "
                    "lines (left green, right a colour per frame), a red band at the top when it "
                    "started over (a reset: the frame copied, not generated), a blue one below "
                    "when it saw a scene change");

REXCVAR_DEFINE_BOOL(rexnative_frame_generation_debug, false, "ReXNative",
                    "FidelityFX's debug view in the generated frames (live): its inputs and "
                    "internal surfaces (motion vectors, optical flow, disocclusion) in a grid");

REXCVAR_DEFINE_DOUBLE(rexnative_frame_generation_sharpness, 0.5, "ReXNative",
                      "Sharpening of the generated frames where the scene moves (FSR 1's RCAS, "
                      "0 to 1; 0 off; live): FidelityFX samples both frames between their pixels "
                      "and blends them, so its frames are softer than the real ones, and fine "
                      "detail (leaves, grass, tyres) pulsed between sharp and soft at 30 Hz");

REXCVAR_DEFINE_BOOL(rexnative_frame_generation_check, false, "ReXNative",
                    "FidelityFX checks the frame generation's inputs and logs what it finds "
                    "wrong (FFX_FRAMEGENERATION_ENABLE_DEBUG_CHECKING; when the context is "
                    "made)");

namespace {
// FidelityFX's messages, into the log.
void FgMessage(uint32_t type, const wchar_t* message) {
  std::string s;
  for (const wchar_t* p = message; p && *p; ++p) s += *p < 128 ? char(*p) : '?';
  if (type == FFX_API_MESSAGE_TYPE_ERROR)
    REXNATIVE_LOG_FIRST(32, ERROR, "ReXNative frame generation (FidelityFX): {}", s);
  else
    REXNATIVE_LOG_FIRST(32, WARN, "ReXNative frame generation (FidelityFX): {}", s);
}
}  // namespace

bool FrameGeneration::Requested() { return REXCVAR_GET(rexnative_frame_generation); }

FrameGeneration::~FrameGeneration() { Destroy(); }

bool FrameGeneration::Initialize() {
  D3D12_DESCRIPTOR_HEAP_DESC hd = {};
  hd.Type = D3D12_DESCRIPTOR_HEAP_TYPE_RTV;
  hd.NumDescriptors = 2;
  rtv_stride_ = device_.device()->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_RTV);
  return !Failed(device_.device()->CreateDescriptorHeap(&hd, IID_PPV_ARGS(&rtv_heap_)),
                 "CreateDescriptorHeap(frame generation RTVs)");
}

D3D12_CPU_DESCRIPTOR_HANDLE FrameGeneration::Rtv(uint32_t i) const {
  D3D12_CPU_DESCRIPTOR_HANDLE h = rtv_heap_->GetCPUDescriptorHandleForHeapStart();
  h.ptr += size_t(i) * rtv_stride_;
  return h;
}

void FrameGeneration::OnSwap(uint32_t front_base) {
  if (last_resolve_.source < 4 && last_resolve_.dest_base == front_base)
    front_ = last_resolve_;
  else
    front_.reset();
}

bool FrameGeneration::CopyAtHud(CommandStream* list, uint64_t frame, const uint32_t* regs,
                                uint64_t pass, SceneStage stage) {
  if (!REXCVAR_GET(rexnative_frame_generation_hudless)) return false;
  const SurfaceRegs& f = front_->regs;
  // A game whose front buffer is resolved from the scene's surface itself (Jet Set Radio: its
  // characters, their outlines and its HUD all drawn into the scene, blended after opaque
  // draws): the early resolve would be the scene's, which runs the upscaler there, before the
  // draws after it (headless characters in every frame). No HUD-less copy there: its HUD is
  // generated with the rest of the image. PGR4 composites into a surface of its own. A game that
  // goes on drawing into the scene's surface after its upscaled resolve (Dark Souls II,
  // Minecraft: post-processing, then the HUD) draws there into the upscaler's full-size target
  // (Upscaler::EnterPostScene), which the early resolve copies as it is: from the upscaled
  // resolve on, its draws are watched as another game's into its front buffer, the copy made
  // once the full-size target is in place. Without it their HUD was generated with the scene,
  // doubled and smeared in the generated frames as the view moved.
  const bool scene_front = IsSceneSurface(f.surface_info);
  if (scene_front && stage == SceneStage::kScene) return false;
  // RT 0 of the draw is the front buffer's surface (pitch, MSAA, EDRAM data), written.
  if (regs[XE_GPU_REG_RB_SURFACE_INFO] != f.surface_info ||
      ColorStorage(regs[XE_GPU_REG_RB_COLOR_INFO]) != ColorStorage(f.color_info[front_->source]) ||
      !(regs[XE_GPU_REG_RB_COLOR_MASK] & 0x7))
    return false;
  // RB_BLENDCONTROL0's color part: source ONE, ADD, destination ZERO replaces what was there.
  if ((regs[XE_GPU_REG_RB_BLENDCONTROL0] & 0x1FFF) == 0x0001) {
    // A composite (again: a copy made before it is the scene's, made again after it).
    composited_frame_ = frame;
    blended_ = 0;
    frame_blends_.clear();
    if (copy_frame_ == frame) copy_frame_ = UINT64_MAX;
    return false;
  }
  if (composited_frame_ != frame) return false;
  const uint32_t index = blended_++;
  if (frame_blends_.size() < 32) frame_blends_.push_back(pass);
  if (copy_frame_ == frame) return false;
  // A full-screen pass learned before the HUD: the copy waits for it.
  if (index < post_passes_.size() && post_passes_[index] == pass) return false;
  if (scene_front && stage != SceneStage::kPostScene) return false;
  copy_frame_ = frame;
  copy_index_ = index;
  copy_ = resolver_.ResolveCopy(list, *front_);
  return true;
}

namespace {
// CompositeHud, from FidelityFX's frame (t2) into the generated frame (u0). With `hud`: where the
// frame (t0) and its HUD-less copy (t1) differ in a 3x3 neighbourhood by more than the copy's
// rounding (3 steps of 8 bits, 12 of 10), the frame's pixel. Elsewhere FidelityFX's, sharpened by
// FSR 1's RCAS (its lobe and limits, without the noise detection) by `sharpness` times the
// pixel's motion in pixels, up to 1 (the scene's motion vectors, t3, UV, at their own size): a
// still pixel is the real one's, as sharp. `origin` and `size`: the generation rect.
constexpr char kHudHlsl[] = R"(
Texture2D<float4> frame : register(t0);
Texture2D<float4> hudless : register(t1);
Texture2D<float4> raw : register(t2);
Texture2D<float2> motion : register(t3);
RWTexture2D<float4> generated : register(u0);
cbuffer Constants : register(b0) {
  uint2 origin; uint2 size; uint2 motion_size; uint hud; float sharpness;
};
[numthreads(8, 8, 1)]
void main(uint2 id : SV_DispatchThreadID) {
  if (any(id >= size)) return;
  const int2 p = int2(origin + id);
  const int2 lo = int2(origin), hi = int2(origin + size) - 1;
  if (hud != 0) {
    float d = 0.0;
    [unroll] for (int y = -1; y <= 1; ++y) {
      [unroll] for (int x = -1; x <= 1; ++x) {
        const int3 q = int3(clamp(p + int2(x, y), lo, hi), 0);
        const float3 e = abs(frame.Load(q).rgb - hudless.Load(q).rgb);
        d = max(d, max(e.r, max(e.g, e.b)));
      }
    }
    if (d > 0.0125) {
      generated[p] = frame.Load(int3(p, 0));
      return;
    }
  }
  const float4 e = raw.Load(int3(p, 0));
  float s = 0.0;
  if (sharpness > 0.0 && motion_size.x != 0) {
    const int2 m = min(int2((float2(id) + 0.5) * float2(motion_size) / float2(size)),
                       int2(motion_size) - 1);
    s = sharpness * saturate(length(motion.Load(int3(m, 0)) * float2(size)));
  }
  if (s <= 0.0) {
    generated[p] = e;
    return;
  }
  const float3 b = raw.Load(int3(clamp(p + int2(0, -1), lo, hi), 0)).rgb;
  const float3 h = raw.Load(int3(clamp(p + int2(0, 1), lo, hi), 0)).rgb;
  const float3 l = raw.Load(int3(clamp(p + int2(-1, 0), lo, hi), 0)).rgb;
  const float3 r = raw.Load(int3(clamp(p + int2(1, 0), lo, hi), 0)).rgb;
  const float3 mn = min(min(min(b, h), min(l, r)), e.rgb);
  const float3 mx = max(max(max(b, h), max(l, r)), e.rgb);
  const float3 hit_min = mn / (4.0 * mx + 1e-6);
  const float3 hit_max = (1.0 - mx) / (4.0 * mn - 4.0 - 1e-6);
  const float3 lobes = max(-hit_min, hit_max);
  const float lobe = max(-0.1875, min(max(lobes.r, max(lobes.g, lobes.b)), 0.0)) * s;
  generated[p] = float4(saturate((lobe * (b + h + l + r) + e.rgb) / (4.0 * lobe + 1.0)), e.a);
}
)";
}  // namespace

bool FrameGeneration::CreateHudPass() {
  if (hud_tried_) return hud_ok_;
  hud_tried_ = true;
  ID3D12Device* device = device_.device();
  const D3D12_DESCRIPTOR_RANGE ranges[2] = {
      {D3D12_DESCRIPTOR_RANGE_TYPE_SRV, 4, 0, 0, 0},
      {D3D12_DESCRIPTOR_RANGE_TYPE_UAV, 1, 0, 0, 4},
  };
  D3D12_ROOT_PARAMETER params[2] = {};
  params[0].ParameterType = D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;
  params[0].DescriptorTable = {2, ranges};
  params[1].ParameterType = D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;
  params[1].Constants = {0, 0, 8};
  const D3D12_ROOT_SIGNATURE_DESC rs = {2, params, 0, nullptr, D3D12_ROOT_SIGNATURE_FLAG_NONE};
  ComPtr<ID3DBlob> blob, err;
  const D3D12_DESCRIPTOR_HEAP_DESC hd = {D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV, 5,
                                         D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE, 0};
  if (Failed(D3D12SerializeRootSignature(&rs, D3D_ROOT_SIGNATURE_VERSION_1, &blob, &err),
             "frame generation HUD root signature serialize") ||
      Failed(device->CreateRootSignature(0, blob->GetBufferPointer(), blob->GetBufferSize(),
                                         IID_PPV_ARGS(&hud_signature_)),
             "frame generation HUD root signature") ||
      Failed(device->CreateDescriptorHeap(&hd, IID_PPV_ARGS(&hud_heap_)),
             "frame generation HUD heap"))
    return false;
  hud_stride_ = device->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
  const pD3DCompile compile = D3DCompiler();
  constexpr char kName[] = "rexnative_frame_generation_hud.hlsl";
  ComPtr<ID3DBlob> code, error;
  if (!compile || FAILED(compile(kHudHlsl, sizeof(kHudHlsl) - 1, kName, nullptr, nullptr, "main",
                                 "cs_5_0", D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &code, &error))) {
    REXLOG_ERROR("ReXNative frame generation: {}: {}", kName,
                 error ? static_cast<const char*>(error->GetBufferPointer()) : "?");
    return false;
  }
  D3D12_COMPUTE_PIPELINE_STATE_DESC pd = {};
  pd.pRootSignature = hud_signature_.Get();
  pd.CS = {code->GetBufferPointer(), code->GetBufferSize()};
  hud_ok_ = !Failed(device->CreateComputePipelineState(&pd, IID_PPV_ARGS(&hud_pso_)), kName);
  return hud_ok_;
}

void FrameGeneration::WriteHudViews() {
  if (!hud_ok_ || !image_) return;
  ID3D12Device* device = device_.device();
  const DXGI_FORMAT format = image_->GetDesc().Format;
  D3D12_CPU_DESCRIPTOR_HANDLE cpu = hud_heap_->GetCPUDescriptorHandleForHeapStart();
  D3D12_SHADER_RESOURCE_VIEW_DESC sd = {};
  sd.Format = format;
  sd.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
  sd.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
  sd.Texture2D.MipLevels = 1;
  device->CreateShaderResourceView(image_.Get(), &sd, cpu);
  cpu.ptr += hud_stride_;
  device->CreateShaderResourceView(hudless_.Get(), &sd, cpu);
  cpu.ptr += hud_stride_;
  device->CreateShaderResourceView(raw_.Get(), &sd, cpu);
  cpu.ptr += hud_stride_;
  WriteMotionView(nullptr);
  cpu.ptr += hud_stride_;
  D3D12_UNORDERED_ACCESS_VIEW_DESC ud = {};
  ud.Format = format;
  ud.ViewDimension = D3D12_UAV_DIMENSION_TEXTURE2D;
  device->CreateUnorderedAccessView(output_.Get(), nullptr, &ud, cpu);
}

void FrameGeneration::WriteMotionView(ID3D12Resource* motion) {
  D3D12_CPU_DESCRIPTOR_HANDLE cpu = hud_heap_->GetCPUDescriptorHandleForHeapStart();
  cpu.ptr += 3 * hud_stride_;
  D3D12_SHADER_RESOURCE_VIEW_DESC sd = {};
  sd.Format = DXGI_FORMAT_R16G16_FLOAT;
  sd.ViewDimension = D3D12_SRV_DIMENSION_TEXTURE2D;
  sd.Shader4ComponentMapping = D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING;
  sd.Texture2D.MipLevels = 1;
  device_.device()->CreateShaderResourceView(motion, &sd, cpu);
  motion_view_ = motion;
}

void FrameGeneration::CompositeHud(CommandStream* list, FfxApiRect2D rect, bool hud,
                                   ID3D12Resource* motion, uint32_t motion_width,
                                   uint32_t motion_height) {
  // The motion vectors' view: written again only for another resource (the upscaler made its
  // targets again), with the GPU idle, as frames in flight read the one there.
  if (motion != motion_view_) {
    if (motion_view_) device_.WaitIdle();
    WriteMotionView(motion);
  }
  const float sharpness =
      motion ? float(std::clamp(REXCVAR_GET(rexnative_frame_generation_sharpness), 0.0, 1.0))
             : 0.0f;
  uint32_t c[8] = {uint32_t(rect.left), uint32_t(rect.top), uint32_t(rect.width),
                   uint32_t(rect.height), motion ? motion_width : 0u, motion ? motion_height : 0u,
                   hud ? 1u : 0u, 0};
  std::memcpy(&c[7], &sharpness, 4);
  list->Call([this, c](CommandStream::List* l) {
    D3D12_RESOURCE_BARRIER b[4] = {};
    ID3D12Resource* const res[4] = {image_.Get(), hudless_.Get(), raw_.Get(), output_.Get()};
    const D3D12_RESOURCE_STATES to[4] = {D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,
                                         D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,
                                         D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE,
                                         D3D12_RESOURCE_STATE_UNORDERED_ACCESS};
    for (int i = 0; i < 4; ++i) {
      b[i].Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
      b[i].Transition.pResource = res[i];
      b[i].Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
      b[i].Transition.StateBefore = D3D12_RESOURCE_STATE_PRESENT;
      b[i].Transition.StateAfter = to[i];
    }
    l->ResourceBarrier(4, b);
    ID3D12DescriptorHeap* heaps[] = {hud_heap_.Get()};
    l->SetDescriptorHeaps(1, heaps);
    l->SetComputeRootSignature(hud_signature_.Get());
    l->SetPipelineState(hud_pso_.Get());
    l->SetComputeRootDescriptorTable(0, hud_heap_->GetGPUDescriptorHandleForHeapStart());
    l->SetComputeRoot32BitConstants(1, 8, c, 0);
    l->Dispatch((c[2] + 7) / 8, (c[3] + 7) / 8, 1);
    for (D3D12_RESOURCE_BARRIER& x : b)
      std::swap(x.Transition.StateBefore, x.Transition.StateAfter);
    l->ResourceBarrier(4, b);
  });
}

void FrameGeneration::Release() {
  if (!context_ && !image_) return;
  device_.WaitIdle();
  Destroy();
  prepared_frame_ = UINT64_MAX;
  REXLOG_INFO("ReXNative frame generation: off");
}

void FrameGeneration::Destroy() {
  if (context_) api_->destroy(&context_, nullptr);
  context_ = nullptr;
  image_.Reset();
  hudless_.Reset();
  output_.Reset();
  raw_.Reset();
  width_ = height_ = 0;
}

bool FrameGeneration::Resize(uint32_t width, uint32_t height, bool hdr, bool depth_inverted,
                             bool debug) {
  if (context_ && width == width_ && height == height_ && hdr == hdr_ &&
      depth_inverted == depth_inverted_ && debug == debug_)
    return true;
  device_.WaitIdle();
  Destroy();
  const DXGI_FORMAT format =
      hdr ? D3D12Device::kHdrBackBufferFormat : D3D12Device::kBackBufferFormat;
  ID3D12Device* device = device_.device();
  const D3D12_HEAP_PROPERTIES heap = {D3D12_HEAP_TYPE_DEFAULT};
  D3D12_RESOURCE_DESC rd = {
      D3D12_RESOURCE_DIMENSION_TEXTURE2D, 0, width, height, 1, 1, format, {1, 0}};
  rd.Flags = D3D12_RESOURCE_FLAG_ALLOW_RENDER_TARGET;
  if (Failed(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &rd,
                                             D3D12_RESOURCE_STATE_PRESENT, nullptr,
                                             IID_PPV_ARGS(&image_)),
             "CreateCommittedResource(frame generation image)") ||
      Failed(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &rd,
                                             D3D12_RESOURCE_STATE_PRESENT, nullptr,
                                             IID_PPV_ARGS(&hudless_)),
             "CreateCommittedResource(frame generation HUD-less image)"))
    return false;
  rd.Flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;
  if (Failed(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &rd,
                                             D3D12_RESOURCE_STATE_PRESENT, nullptr,
                                             IID_PPV_ARGS(&output_)),
             "CreateCommittedResource(generated frame)") ||
      Failed(device->CreateCommittedResource(&heap, D3D12_HEAP_FLAG_NONE, &rd,
                                             D3D12_RESOURCE_STATE_PRESENT, nullptr,
                                             IID_PPV_ARGS(&raw_)),
             "CreateCommittedResource(FidelityFX's generated frame)"))
    return false;
  device->CreateRenderTargetView(image_.Get(), nullptr, image_rtv());
  device->CreateRenderTargetView(hudless_.Get(), nullptr, hudless_rtv());
  if (CreateHudPass()) WriteHudViews();

  ffxCreateBackendDX12Desc backend = {};
  backend.header.type = FFX_API_CREATE_CONTEXT_DESC_TYPE_BACKEND_DX12;
  backend.device = device;
  ffxCreateContextDescFrameGenerationVersion version = {};
  version.header.type = FFX_API_CREATE_CONTEXT_DESC_TYPE_FRAMEGENERATION_VERSION;
  version.header.pNext = &backend.header;
  version.version = FFX_FRAMEGENERATION_VERSION;
  ffxCreateContextDescFrameGeneration cd = {};
  cd.header.type = FFX_API_CREATE_CONTEXT_DESC_TYPE_FRAMEGENERATION;
  cd.header.pNext = &version.header;
  // The game's scene depth, reversed (cleared to 0) or not (Upscaler::SceneKind); with HDR the
  // image is PQ.
  cd.flags = (depth_inverted ? FFX_FRAMEGENERATION_ENABLE_DEPTH_INVERTED : 0u) |
             (hdr ? FFX_FRAMEGENERATION_ENABLE_HIGH_DYNAMIC_RANGE : 0u) |
             (REXCVAR_GET(rexnative_frame_generation_check)
                  ? FFX_FRAMEGENERATION_ENABLE_DEBUG_CHECKING
                  : 0u);
  cd.displaySize = {width, height};
  cd.maxRenderSize = {SceneWidth(), SceneHeight()};
  cd.backBufferFormat = ffxApiGetSurfaceFormatDX12(format);
  SetFfxWatermark(L"MLFI-WATERMARK", debug);
  if (const ffxReturnCode_t rc = api_->create(&context_, &cd.header, nullptr);
      rc != FFX_API_RETURN_OK) {
    REXLOG_ERROR("ReXNative frame generation: ffxCreateContext failed ({})", rc);
    context_ = nullptr;
    return false;
  }
  if (REXCVAR_GET(rexnative_frame_generation_check)) {
    ffxConfigureDescGlobalDebug g = {};
    g.header.type = FFX_API_CONFIGURE_DESC_TYPE_GLOBALDEBUG;
    g.effectId = FFX_API_EFFECT_ID_FRAMEGENERATION;
    g.fpMessage = FgMessage;
    g.debugLevel = 1;
    if (api_->configure(&context_, &g.header) != FFX_API_RETURN_OK)
      REXLOG_WARN("ReXNative frame generation: FidelityFX's message callback refused");
  }
  width_ = width;
  height_ = height;
  hdr_ = hdr;
  depth_inverted_ = depth_inverted;
  debug_ = debug;
  // The provider the loader picked: 4.x (machine learning) on RDNA 4, 3.1.x elsewhere.
  ffxQueryGetProviderVersion provider = {};
  provider.header.type = FFX_API_QUERY_DESC_TYPE_GET_PROVIDER_VERSION;
  const char* name = api_->query(&context_, &provider.header) == FFX_API_RETURN_OK &&
                             provider.versionName
                         ? provider.versionName
                         : "?";
  REXLOG_INFO("ReXNative frame generation: {} {}x{}{}{}", name, width, height,
              hdr ? " HDR10" : "", debug ? ", debug view" : "");
  return true;
}

void FrameGeneration::Prepare(uint64_t frame, CommandStream* list, const FfxApiResource& depth,
                              const FfxApiResource& motion, FfxApiDimensions2D render_size,
                              FfxApiFloatCoords2D jitter, FfxApiFloatCoords2D motion_scale,
                              const FfxCamera& camera, float frame_ms, bool reset,
                              bool depth_inverted) {
  if (!api_ && !(api_ = LoadFfxApi())) {
    REXNATIVE_WARN_ONCE("ReXNative frame generation: unavailable without the FidelityFX loader");
    return;
  }
  if (!device_.has_swapchain() ||
      !Resize(device_.width(), device_.height(), device_.hdr(), depth_inverted, FfxDebug()))
    return;
  ffxDispatchDescFrameGenerationPrepareV2 d = {};
  d.header.type = FFX_API_DISPATCH_DESC_TYPE_FRAMEGENERATION_PREPARE_V2;
  d.frameID = frame;
  d.renderSize = render_size;
  d.jitterOffset = jitter;
  d.motionVectorScale = motion_scale;
  d.frameTimeDelta = frame_ms;
  d.reset = reset;
  resets_ += reset ? 1 : 0;
  d.cameraNear = camera.near_plane;
  d.cameraFar = camera.far_plane;
  d.cameraFovAngleVertical = camera.fov_y;
  d.viewSpaceToMetersFactor = 1.0f;
  d.depth = depth;
  d.motionVectors = motion;
  // On the stream's thread, which records the list (as Generate's).
  list->Call([this, d](CommandStream::List* l) mutable {
    d.commandList = l;
    if (const ffxReturnCode_t rc = api_->dispatch(&context_, &d.header); rc != FFX_API_RETURN_OK)
      REXNATIVE_WARN_ONCE("ReXNative frame generation: prepare failed ({})", rc);
  });
  prepared_frame_ = frame;
}

void FrameGeneration::Capture(CommandStream* list, uint64_t frame, uint64_t fence,
                              std::filesystem::path dir, bool hudless, ID3D12Resource* motion) {
  if (!context_ || captures_.size() >= 16) return;
  ID3D12Device* device = device_.device();
  PendingCapture c;
  c.frame = frame;
  c.fence = fence;
  c.hdr = hdr_;
  c.dir = std::move(dir);
  const D3D12_RESOURCE_DESC desc = image_->GetDesc();
  UINT64 total = 0;
  device->GetCopyableFootprints(&desc, 0, 1, 0, &c.footprint, nullptr, nullptr, &total);
  ComPtr<ID3D12Resource>* const readbacks[3] = {&c.real, &c.generated, &c.hudless};
  for (uint32_t i = 0; i < (hudless ? 3u : 2u); ++i)
    if (!CreateBuffer(device, D3D12_HEAP_TYPE_READBACK, total, D3D12_RESOURCE_STATE_COPY_DEST,
                      "frame generation capture", readbacks[i]))
      return;
  list->Call([sources = std::array<ID3D12Resource*, 3>{image_.Get(), output_.Get(),
                                                        hudless_.Get()},
              dests = std::array<ID3D12Resource*, 3>{c.real.Get(), c.generated.Get(),
                                                      c.hudless.Get()},
              n = hudless ? 3u : 2u, fp = c.footprint](CommandStream::List* l) {
    D3D12_RESOURCE_BARRIER b[3] = {};
    for (uint32_t i = 0; i < n; ++i) {
      b[i].Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
      b[i].Transition.pResource = sources[i];
      b[i].Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
      b[i].Transition.StateBefore = D3D12_RESOURCE_STATE_PRESENT;
      b[i].Transition.StateAfter = D3D12_RESOURCE_STATE_COPY_SOURCE;
    }
    l->ResourceBarrier(n, b);
    for (uint32_t i = 0; i < n; ++i) {
      D3D12_TEXTURE_COPY_LOCATION dst = {}, src = {};
      dst.pResource = dests[i];
      dst.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
      dst.PlacedFootprint = fp;
      src.pResource = sources[i];
      src.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
      l->CopyTextureRegion(&dst, 0, 0, 0, &src, nullptr);
    }
    for (uint32_t i = 0; i < n; ++i)
      std::swap(b[i].Transition.StateBefore, b[i].Transition.StateAfter);
    l->ResourceBarrier(n, b);
  });
  if (motion) {
    const D3D12_RESOURCE_DESC md = motion->GetDesc();
    UINT64 bytes = 0;
    device->GetCopyableFootprints(&md, 0, 1, 0, &c.motion_footprint, nullptr, nullptr, &bytes);
    if (CreateBuffer(device, D3D12_HEAP_TYPE_READBACK, bytes, D3D12_RESOURCE_STATE_COPY_DEST,
                     "frame generation motion capture", &c.motion))
      list->Call([motion, dest = c.motion.Get(), fp = c.motion_footprint](CommandStream::List* l) {
        D3D12_RESOURCE_BARRIER b = {};
        b.Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
        b.Transition.pResource = motion;
        b.Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
        b.Transition.StateBefore = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
        b.Transition.StateAfter = D3D12_RESOURCE_STATE_COPY_SOURCE;
        l->ResourceBarrier(1, &b);
        D3D12_TEXTURE_COPY_LOCATION dst = {}, src = {};
        dst.pResource = dest;
        dst.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
        dst.PlacedFootprint = fp;
        src.pResource = motion;
        src.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
        l->CopyTextureRegion(&dst, 0, 0, 0, &src, nullptr);
        std::swap(b.Transition.StateBefore, b.Transition.StateAfter);
        l->ResourceBarrier(1, &b);
      });
  }
  captures_.push_back(std::move(c));
}

void FrameGeneration::MeasureHudless(CommandStream* list, uint64_t frame, uint64_t fence) {
  if (measure_.pending || ++measured_frames_ < 15 || !context_) return;
  measured_frames_ = 0;
  Measure& m = measure_;
  if (!m.image) {
    const D3D12_RESOURCE_DESC desc = image_->GetDesc();
    UINT64 total = 0;
    device_.device()->GetCopyableFootprints(&desc, 0, 1, 0, &m.footprint, nullptr, nullptr,
                                            &total);
    if (!CreateBuffer(device_.device(), D3D12_HEAP_TYPE_READBACK, total,
                      D3D12_RESOURCE_STATE_COPY_DEST, "frame generation HUD-less check",
                      &m.image) ||
        !CreateBuffer(device_.device(), D3D12_HEAP_TYPE_READBACK, total,
                      D3D12_RESOURCE_STATE_COPY_DEST, "frame generation HUD-less check",
                      &m.hudless)) {
      m.image.Reset();
      return;
    }
  }
  m.pending = true;
  m.frame = frame;
  m.fence = fence;
  m.copy_index = copy_index_;
  m.blends = frame_blends_;
  list->Call([sources = std::array<ID3D12Resource*, 2>{image_.Get(), hudless_.Get()},
              dests = std::array<ID3D12Resource*, 2>{m.image.Get(), m.hudless.Get()},
              fp = m.footprint](CommandStream::List* l) {
    D3D12_RESOURCE_BARRIER b[2] = {};
    for (int i = 0; i < 2; ++i) {
      b[i].Type = D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;
      b[i].Transition.pResource = sources[i];
      b[i].Transition.Subresource = D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;
      b[i].Transition.StateBefore = D3D12_RESOURCE_STATE_PRESENT;
      b[i].Transition.StateAfter = D3D12_RESOURCE_STATE_COPY_SOURCE;
    }
    l->ResourceBarrier(2, b);
    for (int i = 0; i < 2; ++i) {
      D3D12_TEXTURE_COPY_LOCATION dst = {}, src = {};
      dst.pResource = dests[i];
      dst.Type = D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;
      dst.PlacedFootprint = fp;
      src.pResource = sources[i];
      src.Type = D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;
      l->CopyTextureRegion(&dst, 0, 0, 0, &src, nullptr);
    }
    for (D3D12_RESOURCE_BARRIER& x : b)
      std::swap(x.Transition.StateBefore, x.Transition.StateAfter);
    l->ResourceBarrier(2, b);
  });
}

double FrameGeneration::HudlessDifference() const {
  const Measure& m = measure_;
  const D3D12_SUBRESOURCE_FOOTPRINT& f = m.footprint.Footprint;
  void *pa = nullptr, *pb = nullptr;
  const D3D12_RANGE range = {0, SIZE_T(f.RowPitch) * f.Height};
  const D3D12_RANGE none = {0, 0};
  if (FAILED(m.image->Map(0, &range, &pa))) return -1.0;
  if (FAILED(m.hudless->Map(0, &range, &pb))) {
    m.image->Unmap(0, &none);
    return -1.0;
  }
  // 8 bits a channel (SDR) or 10 (HDR10): a few steps of difference are the copy's rounding.
  const bool ten = f.Format == DXGI_FORMAT_R10G10B10A2_UNORM;
  const uint32_t bits = ten ? 10 : 8, mask = (1u << bits) - 1, tolerance = ten ? 12 : 3;
  uint64_t samples = 0, differ = 0;
  for (uint32_t y = 0; y < f.Height; y += 4) {
    const auto* ra = reinterpret_cast<const uint32_t*>(static_cast<const uint8_t*>(pa) +
                                                       size_t(y) * f.RowPitch);
    const auto* rb = reinterpret_cast<const uint32_t*>(static_cast<const uint8_t*>(pb) +
                                                       size_t(y) * f.RowPitch);
    for (uint32_t x = 0; x < f.Width; x += 4) {
      ++samples;
      for (uint32_t c = 0; c < 3; ++c) {
        const int32_t a = int32_t((ra[x] >> (bits * c)) & mask),
                      b = int32_t((rb[x] >> (bits * c)) & mask);
        if (uint32_t(a > b ? a - b : b - a) > tolerance) {
          ++differ;
          break;
        }
      }
    }
  }
  m.image->Unmap(0, &none);
  m.hudless->Unmap(0, &none);
  return samples ? double(differ) / double(samples) : -1.0;
}

void FrameGeneration::FinishCaptures(uint64_t completed_fence) {
  if (measure_.pending && measure_.fence <= completed_fence) {
    measure_.pending = false;
    const double d = HudlessDifference();
    const Measure& m = measure_;
    // Most of the image differs: the blended draws up to the copy point are full-screen passes
    // (a HUD covers less). Learn them; the next frames copy after them.
    if (d > 0.5 && m.copy_index < m.blends.size() && m.copy_index < 16) {
      post_passes_.assign(m.blends.begin(), m.blends.begin() + m.copy_index + 1);
      if (++hudless_logs_ <= 8)
        REXLOG_INFO("ReXNative frame generation: the HUD-less copy differed from frame {} in "
                    "{:.0f}% of its pixels; it now waits for {} full-screen pass(es)",
                    m.frame, 100.0 * d, post_passes_.size());
    } else if (d >= 0.0 && hudless_logs_ < 8 && (hudless_logs_ == 0 || d > 0.5)) {
      ++hudless_logs_;
      REXLOG_INFO("ReXNative frame generation: the HUD-less copy differs from frame {} in "
                  "{:.1f}% of its pixels (after {} full-screen pass(es))",
                  m.frame, 100.0 * d, post_passes_.size());
    }
  }
  static constexpr const char* kNames[3] = {"-fg-real.png", "-fg-generated.png",
                                            "-fg-hudless.png"};
  while (!captures_.empty() && captures_.front().fence <= completed_fence) {
    PendingCapture& c = captures_.front();
    const D3D12_SUBRESOURCE_FOOTPRINT& f = c.footprint.Footprint;
    ID3D12Resource* const readbacks[3] = {c.real.Get(), c.generated.Get(), c.hudless.Get()};
    // The texels are copied out here and converted and written by a thread of its own: written
    // on this thread (three PNGs a frame, eight frames in a row) they held the frames back, and a
    // game that moves by the clock (Sega Rally Revo) jumped up to half a second between the
    // frames captured, so the generated ones looked far worse than in play.
    struct Image {
      std::vector<uint8_t> texels;
      std::filesystem::path path;
    };
    std::vector<Image> images;
    for (uint32_t i = 0; i < 3; ++i) {
      ID3D12Resource* readback = readbacks[i];
      void* p = nullptr;
      const SIZE_T bytes = SIZE_T(f.RowPitch) * f.Height;
      const D3D12_RANGE range = {0, bytes};
      if (!readback || FAILED(readback->Map(0, &range, &p))) continue;
      Image& im = images.emplace_back();
      im.texels.assign(static_cast<const uint8_t*>(p), static_cast<const uint8_t*>(p) + bytes);
      im.path = c.dir / ("f" + std::to_string(c.frame) + kNames[i]);
      const D3D12_RANGE none = {0, 0};
      readback->Unmap(0, &none);
    }
    // The motion vectors: "RXMV", width, height, then the rows without their padding.
    std::vector<uint8_t> motion;
    std::filesystem::path motion_path;
    if (c.motion) {
      const D3D12_SUBRESOURCE_FOOTPRINT& mf = c.motion_footprint.Footprint;
      void* p = nullptr;
      const D3D12_RANGE range = {0, SIZE_T(mf.RowPitch) * mf.Height};
      if (SUCCEEDED(c.motion->Map(0, &range, &p))) {
        const uint32_t row = mf.Width * 4, header[3] = {0x564D5852u, mf.Width, mf.Height};
        motion.resize(sizeof(header) + size_t(row) * mf.Height);
        std::memcpy(motion.data(), header, sizeof(header));
        for (uint32_t y = 0; y < mf.Height; ++y)
          std::memcpy(motion.data() + sizeof(header) + size_t(row) * y,
                      static_cast<const uint8_t*>(p) + size_t(mf.RowPitch) * y, row);
        const D3D12_RANGE none = {0, 0};
        c.motion->Unmap(0, &none);
        motion_path = c.dir / ("f" + std::to_string(c.frame) + "-fg-motion.raw");
      }
    }
    std::thread([images = std::move(images), pitch = f.RowPitch, w = f.Width, h = f.Height,
                 hdr = c.hdr, motion = std::move(motion), motion_path] {
      if (!motion.empty())
        if (std::FILE* file = _wfopen(motion_path.c_str(), L"wb")) {
          std::fwrite(motion.data(), 1, motion.size(), file);
          std::fclose(file);
        }
      for (const Image& im : images) {
        std::vector<uint8_t> rgb;
        present_debug::ToRgb(im.texels.data(), pitch, w, h,
                             D3D12_DEFAULT_SHADER_4_COMPONENT_MAPPING, hdr, &rgb);
        present_debug::WritePng(im.path.c_str(), rgb, w, h);
      }
    }).detach();
    REXLOG_INFO("ReXNative frame generation: capture of frame {} ({})", c.frame,
                c.dir.string());
    captures_.erase(captures_.begin());
  }
}

ID3D12Resource* FrameGeneration::Generate(CommandStream* list, uint64_t frame, FfxApiRect2D rect,
                                          bool hudless, ID3D12Resource* motion,
                                          uint32_t motion_width, uint32_t motion_height) {
  ffxConfigureDescFrameGeneration c = {};
  c.header.type = FFX_API_CONFIGURE_DESC_TYPE_FRAMEGENERATION;
  c.frameGenerationEnabled = true;
  c.flags = FFX_FRAMEGENERATION_FLAG_NO_SWAPCHAIN_CONTEXT_NOTIFY;
  if (debug_ || REXCVAR_GET(rexnative_frame_generation_debug))
    c.flags |= FFX_FRAMEGENERATION_FLAG_DRAW_DEBUG_VIEW;
  if (REXCVAR_GET(rexnative_frame_generation_indicators))
    c.flags |= FFX_FRAMEGENERATION_FLAG_DRAW_DEBUG_TEAR_LINES |
               FFX_FRAMEGENERATION_FLAG_DRAW_DEBUG_RESET_INDICATORS;
  c.generationRect = rect;
  c.frameID = frame;
  REXNATIVE_LOG_FIRST(2, INFO, "ReXNative frame generation: generation rect {},{} {}x{} of {}x{}",
                      rect.left, rect.top, rect.width, rect.height, width_, height_);
  // With the HUD-less copy: FidelityFX generates between the HUD-less copies, and CompositeHud
  // puts the frame's HUD over the result (see frame_generation.h). It also sharpens the result,
  // with or without the copy: FidelityFX's frame goes into raw_ for it.
  const bool own_hud = hudless && hud_ok_;
  ffxDispatchDescFrameGeneration d = {};
  d.header.type = FFX_API_DISPATCH_DESC_TYPE_FRAMEGENERATION;
  d.presentColor = ffxApiGetResourceDX12(own_hud ? hudless_.Get() : image_.Get(),
                                         FFX_API_RESOURCE_STATE_PRESENT);
  d.outputs[0] = ffxApiGetResourceDX12(hud_ok_ ? raw_.Get() : output_.Get(),
                                       FFX_API_RESOURCE_STATE_PRESENT);
  d.numGeneratedFrames = 1;
  d.backbufferTransferFunction =
      hdr_ ? FFX_API_BACKBUFFER_TRANSFER_FUNCTION_PQ : FFX_API_BACKBUFFER_TRANSFER_FUNCTION_SRGB;
  d.minMaxLuminance[1] = device_.hdr_peak_nits();
  d.generationRect = rect;
  d.frameID = frame;
  // On the stream's thread, which records the list: a failure leaves the output unwritten, and
  // shows from the next frame on.
  list->Call([this, c, d](CommandStream::List* l) mutable {
    d.commandList = l;
    ffxReturnCode_t rc = api_->configure(&context_, &c.header);
    if (rc == FFX_API_RETURN_OK) rc = api_->dispatch(&context_, &d.header);
    if (rc != FFX_API_RETURN_OK)
      REXNATIVE_WARN_ONCE("ReXNative frame generation: ffxDispatch failed ({})", rc);
  });
  if (hud_ok_) CompositeHud(list, rect, own_hud, motion, motion_width, motion_height);
  return output_.Get();
}

}  // namespace rexnative
